"""What every target generator provides."""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from ..messages import Msg
from ..model.theme import Theme

# First line of every generated file. A file at a planned path that does not
# start with it was not written by this app and is reported before it is replaced.
MARKER = "# Generated by Plasma Theme Studio."


class ApplyError(Exception):
    def __init__(self, message: Msg):
        self.message = message
        super().__init__(str(message))


@dataclass(frozen=True)
class PlannedFile:
    path: Path
    content: str


class Generator:
    """One target of a theme, for example the Plasma color scheme."""

    id: str = ""
    title: Msg

    def unavailable_reason(self, runner) -> Msg | None:
        """Why this target cannot be applied on this system, or None if it can."""
        return None

    def files(self, theme: Theme) -> list[PlannedFile]:
        raise NotImplementedError

    def check_output(self, file: PlannedFile) -> list[Msg]:
        """Problems with generated content. Anything returned blocks the apply."""
        return []

    def problems(self, theme: Theme) -> list[Msg]:
        """Reasons this theme cannot be applied to this target."""
        return []

    def warnings(self, theme: Theme, runner) -> list[Msg]:
        return []

    def reload_command(self, theme: Theme) -> str:
        """The command shown to the user as the way this target is reloaded."""
        return ""

    def capture_settings(self, runner) -> dict:
        """Desktop settings to store in a snapshot before applying."""
        return {}

    def reload(self, theme: Theme, runner) -> None:
        """Make the desktop use the files that were just written."""

    def restore_settings(self, settings: dict, runner) -> None:
        """Put back the settings stored by `capture_settings`."""
